# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# integration_dmultinom_missing_data ----
## Setup ----
# Remove the year-3 age and length compositions of fleet1 so that FIMSFrame()
# fills both rows with the missing-value code and the multinomial skips them.
na_value <- -999
data("data_big")
data_missing_row <- data_big |>
  dplyr::filter(
    !(type %in% c("age_comp", "length_comp") & fleet == "fleet1" & timing == 3)
  )
data_4_model <- FIMSFrame(data_missing_row)

fit <- setup_default_parameters(data = data_4_model) |>
  initialize_fims(data = data_4_model) |>
  fit_fims(optimize = FALSE)

# One element per bin of every multinomial composition
multinomial_cells <- get_estimates(fit) |>
  dplyr::filter(distribution == "multinomial")
clear()

# One element per composition row, i.e., per distribution and year
multinomial_rows <- multinomial_cells |>
  dplyr::summarize(
    missing = any(observed == na_value),
    n_likelihood_values = dplyr::n_distinct(likelihood),
    .by = c(module_id, label, year_i)
  )

## IO correctness ----
test_that("dmultinom reports one log-likelihood per observed composition row", {
  observed_rows <- dplyr::filter(multinomial_rows, !missing)

  #' @description Test that every bin of an observed composition row reports the same share of the row log-likelihood.
  expect_equal(
    object = unique(observed_rows[["n_likelihood_values"]]),
    expected = 1
  )

  #' @description Test that summing the per-bin likelihood over a composition gives that composition's total lpdf, counting each row once.
  totals <- multinomial_cells |>
    dplyr::summarize(
      sum_cells = sum(likelihood),
      lpdf = dplyr::first(lpdf),
      .by = c(module_id, label)
    )
  # lpdf is written to the output with 6 significant digits
  expect_equal(
    object = totals[["sum_cells"]],
    expected = totals[["lpdf"]],
    tolerance = 1e-5
  )
})

## Edge handling ----
test_that("dmultinom reports zero for composition rows with missing data", {
  #' @description Test that the setup produced one skipped age composition row and one skipped length composition row.
  expect_equal(
    object = sum(multinomial_rows[["missing"]]),
    expected = 2
  )

  missing_rows <- dplyr::filter(multinomial_rows, missing)
  missing_cells <- multinomial_cells |>
    dplyr::semi_join(missing_rows, by = c("module_id", "label", "year_i"))

  #' @description Test that every bin of a composition row with missing data reports a log-likelihood of zero.
  expect_equal(
    object = missing_cells[["likelihood"]],
    expected = rep(0, nrow(missing_cells))
  )
})
